python3 - <<'PY'
from pathlib import Path
import re
root = Path('lib/residency_schedule_web')
pattern = re.compile(r'(?<![\w:-])((?:[\w-]+:|aria-\[current=page\]:)*)(bg-white|(?:bg|text|border|border-l|divide|placeholder|ring)-(?:gray|blue|red|green|amber|yellow|purple|indigo|emerald|violet)-\d+)(/\d+)?(?![\w-])')
bg = {50:950,100:800,200:700,300:600,400:500}
text = {200:600,300:500,400:400,500:300,600:300,700:200,800:100,900:100}
def replace(m):
    prefix, token, opacity = m.group(1), m.group(2), m.group(3) or ''
    if 'dark:' in prefix: return m.group(0)
    if token == 'bg-white': dark = 'bg-gray-900'
    else:
        kind, color, value = token.rsplit('-',2)
        value = int(value)
        if color == 'gray':
            values = bg if kind == 'bg' else text if kind in ['text','placeholder'] else {50:700,100:700,200:700,300:600,400:500}
            if value not in values: return m.group(0)
            dark = f'{kind}-gray-{values[value]}'
        elif kind == 'bg' and value in [50,100,200]: dark = f'bg-{color}-' + ('950' if value == 50 else '900')
        elif kind == 'text' and value >= 500: dark = f'text-{color}-300'
        elif kind.startswith('border') and value <= 300: dark = f'{kind}-{color}-800'
        else: return m.group(0)
    return m.group(0) + ' dark:' + prefix + dark + opacity
for path in root.rglob('*'):
    if path.suffix not in ['.ex','.heex']: continue
    old = path.read_text()
    new = pattern.sub(replace, old)
    if new != old: path.write_text(new)
