+  assert.equal(page.theme(), "dark");
+  page.receive("phx:theme", null);
+  assert.equal(page.theme(), "dark");
+  page.system(false);
+  assert.equal(page.theme(), "light");
+  assert.equal(page.writes.length, before);
+  page.receive("unrelated", "dark");
+  assert.equal(page.theme(), "light");
+});
+
